    for (var i = n - 1; i >= 1; i--) d += ' L' + p[i][0].toFixed(1) + ' ' + p[i][1].toFixed(1);
    d += ' L' + g2[0].toFixed(1) + ' ' + g2[1].toFixed(1);
    add(g, 'path', merge(DEF, { d: d }));
