    var seen = {}; seen[key(byCat)] = 1; var dists = [], guard = 0;
    // گزینه‌های غلطِ near-miss: گروه‌بندیِ درست با فقط ۱ تا ۲ جابه‌جایی (نه به‌هم‌ریختنِ کامل)
