      return function (g) { function shp(t, k) { var p = polyPts(n, 32, 50, 50, st); if (k) add(t, 'polygon', merge(DEF, { points: ptsStr(p) })); else add(t, 'polygon', { points: ptsStr(p) }); } hatchInto(g, shp, ang, 7, 1.7); };
