    while (dists.length < count - 1) { var m = randMask(rng, 2, 5); var k = maskKey(m); if (!seen[k]) { seen[k] = 1; dists.push(m); } }
    var opts = [{ m: C }].concat(dists.map(function (m) { return { m: m }; })); var order = rng.shuffle(opts);
