    for (var i = 0; i < sh.length && dists.length < count - 1; i++) { var k = key(sh[i]); if (!seen[k]) { seen[k] = 1; dists.push(sh[i]); } }
    var opts = [correct].concat(dists); var order = rng.shuffle(opts);
