  // تحلیلِ نقاطِ قوت و ضعف بر اساسِ نوعِ سرنخ
  function tagAnalysis(stats) {
    var rows = [];
    for (var k in stats) rows.push({ tag: k, t: stats[k].t, c: stats[k].c, pct: Math.round(stats[k].c / stats[k].t * 100) });
    if (!rows.length) return null;
    rows.sort(function (a, b) { return a.pct - b.pct || b.t - a.t; });
    var weak = rows.filter(function (r) { return r.pct < 60; });
    var panel = h('div', { class: 'tz-analysis' }, h('div', { class: 'tz-analysis-h' }, '📊 تحلیلِ مهارت‌ها بر اساسِ سرنخ'));
    rows.forEach(function (r) {
      var cls = r.pct >= 80 ? 'good' : r.pct >= 60 ? 'ok' : 'weak';
      panel.appendChild(h('div', { class: 'tz-tagstat ' + cls },
        h('span', { class: 'tz-tagname' }, (r.pct >= 80 ? '💪 ' : r.pct >= 60 ? '👍 ' : '🎯 ') + r.tag),
        h('span', { class: 'tz-tagbar' }, h('span', { class: 'tz-tagfill', style: 'width:' + r.pct + '%' })),
        h('span', { class: 'tz-tagnum' }, toFa(r.c) + '/' + toFa(r.t))));
    });
    panel.appendChild(h('p', { class: 'tz-analysis-tip' },
      weak.length ? 'برای تقویت، درسنامه‌ی این سرنخ‌ها را دوباره ببین: ' + weak.map(function (r) { return r.tag; }).join('، ') + '.'
        : 'آفرین! در همه‌ی سرنخ‌ها خوب بودی. برای چالشِ بیشتر، سختیِ تمرین را بالا ببر.'));
    return panel;
  }
  function runQuiz(m, stage, total, challenge) {
    clear(stage);
    total = total || 15;
    var PERQ = 30;                              // ثانیه برای هر سؤال در حالتِ چالش
    var rng = new RNG((Date.now() & 0xffffff) ^ (m.n * 2654435761) ^ (total * 40503));
    // کیسه‌ی نوع‌ها (تا نوع‌ها پشتِ‌هم تکرار نشوند) + رمپِ سختیِ نرم با پراکندگی
    var bags = {};
    function pickGen(level) { if (!bags[level] || !bags[level].length) bags[level] = rng.shuffle(m.pool(level)); return bags[level].pop(); }
    var qs = [];
    for (var i = 0; i < total; i++) {
      var frac = total > 1 ? i / (total - 1) : 0, r = rng.next(), lv;
      if (frac < 0.34) lv = r < 0.6 ? 1 : 2;
      else if (frac < 0.7) lv = r < 0.5 ? 2 : (r < 0.75 ? 3 : 1);
      else lv = r < 0.72 ? 3 : 2;
      qs.push(pickGen(lv)(rng, lv));
    }
    var idx = 0, correct = 0, wrong = [], stats = {}, streak = 0, bestStreak = 0, review = [], speed = 0, qTimer = null;
    function clearQT() { if (qTimer) { clearInterval(qTimer); qTimer = null; } }
    var bar = h('div', { class: 'tz-barwrap' }, h('div', { class: 'tz-bar' }));
    var box = h('div', {}); stage.appendChild(bar); stage.appendChild(box);
    function draw() {
      clearQT();
      bar.firstChild.style.width = (idx / total * 100) + '%';
      clear(box);
      if (idx >= total) return finish();
      var q = qs[idx];
      box.appendChild(h('div', { class: 'tz-qcount' },
        h('span', {}, 'سؤالِ ' + toFa(idx + 1) + ' از ' + toFa(total)),
        h('span', { class: 'tz-qscore' }, '⭐ ' + toFa(correct) + (challenge && speed ? '   ⚡ ' + toFa(speed) : '') + (streak >= 2 ? '   🔥 ' + toFa(streak) : ''))));
      box.appendChild(h('p', { class: 'tz-qprompt' }, q.prompt));
      var timeFill = null;
      if (challenge) { timeFill = h('div', { class: 'tz-time' }); box.appendChild(h('div', { class: 'tz-timewrap' }, timeFill)); }
      if (q.refs) box.appendChild(refsPanel(q.refs));
      if (q.grid) box.appendChild(gridPanel(q.grid));
      if (q.matrix) box.appendChild(matrixPanel(q.matrix));
      if (q.series) box.appendChild(seriesPanel(q.series));
      var opts = h('div', { class: 'tz-opts' + (q.wide ? ' wide' : '') }); var done = false;
      function reveal(chosen) {
        if (done) return; done = true; clearQT();
        var ok = chosen === q.answer;
        if (chosen >= 0) opts.children[chosen].classList.add(ok ? 'ok' : 'bad');
        opts.children[q.answer].classList.add('ok');
        var tg = q.tag || 'عمومی'; if (!stats[tg]) stats[tg] = { t: 0, c: 0 }; stats[tg].t++; if (ok) stats[tg].c++;
        if (ok) { correct++; streak++; if (streak > bestStreak) bestStreak = streak; if (challenge && timeLeft > PERQ * 0.55) speed++; }
        else { streak = 0; wrong.push(idx + 1); review.push({ q: q, chosen: chosen }); }
        tzSound(ok ? 'ok' : 'bad');
        var praise = chosen < 0 ? '⏱️ وقت تمام شد — پاسخِ درست این بود: ' : ok ? (streak >= 3 ? '🔥 ' + toFa(streak) + ' تایی پشتِ‌هم! آفرین! ' : '✓ درست! ') : '✗ اشتباه — ';
        box.appendChild(h('div', { class: 'tz-fb ' + (ok ? 'ok' : 'bad') }, praise + q.why));
        box.appendChild(h('div', { class: 'tz-lnav' }, h('span'), h('button', { class: 'tz-btn', onclick: function () { idx++; draw(); } }, idx < total - 1 ? 'سؤالِ بعد ←' : 'دیدنِ کارنامه')));
        if (ok && streak >= 3) tzConfetti(stage);
      }
      q.options.forEach(function (o, i) {
        var b = h('button', { class: 'tz-opt', onclick: function () { reveal(i); } }, q.render(o), h('span', { class: 'tz-opt-n' }, toFa(i + 1)));
        opts.appendChild(b);
      });
      box.appendChild(opts);
      var timeLeft = PERQ;
      if (challenge && timeFill) {
        timeFill.style.width = '100%';
        qTimer = setInterval(function () {
          if (!document.body.contains(box)) { clearQT(); return; }   // کاربر صفحه را عوض کرده
          timeLeft--; var pctT = Math.max(0, timeLeft / PERQ * 100);
          timeFill.style.width = pctT + '%';
          timeFill.classList.toggle('low', timeLeft <= 8);
          if (timeLeft <= 0) { clearQT(); reveal(-1); }
        }, 1000);
      }
    }
    function finish() {
      bar.firstChild.style.width = '100%'; clear(box);
      var pct = Math.round(correct / total * 100), st = starsFor(pct);
      saveBest(m.id, pct, true, wrong); progQuiz(m.id, pct, bestStreak);
      var mood = pct >= 70 ? 'wow' : pct >= 40 ? 'happy' : 'hi';
      var msg = st === 3 ? 'فوق‌العاده بود! کارآگاهِ حرفه‌ای شدی 🌟' : st === 2 ? 'آفرین! خیلی خوب بود، یک قدم تا عالی 💪' : st === 1 ? 'شروعِ خوبی بود! با تمرین قوی‌تر می‌شوی 🌱' : 'اشکال ندارد قهرمان، دوباره تلاش کن؛ حتماً بهتر می‌شوی 🌱';
      box.appendChild(h('div', { class: 'tz-report tz-celebrate' },
        tzMascot(mood, 110),
        starRow(st, 3),
        h('div', { class: 'tz-score' }, toFa(correct) + ' / ' + toFa(total)),
        h('div', { class: 'tz-badge' }, '🎖 نشانِ «' + m.title + '»'),
        h('p', { class: 'tz-msg' }, msg),
        bestStreak >= 3 ? h('p', { class: 'tz-streakline' }, '🔥 بهترین زنجیره: ' + toFa(bestStreak) + ' پاسخِ درستِ پشتِ‌هم!') : null,
        (challenge && speed) ? h('p', { class: 'tz-streakline', style: 'background:' + PAL.skyL + ';color:#0284a8' }, '⚡ ' + toFa(speed) + ' پاسخِ سریع — امتیازِ سرعت گرفتی!') : null,
        wrong.length ? h('p', { class: 'tz-wrong' }, 'سؤال‌های اشتباه: ' + wrong.map(toFa).join('، ')) : null,
        tagAnalysis(stats),
        h('div', { class: 'tz-lnav tz-lnav-wrap' },
          review.length ? h('button', { class: 'tz-btn ghost', onclick: function () { reviewWrong(); } }, '🔍 مرورِ اشتباه‌ها (' + toFa(review.length) + ')') : h('span'),
          h('button', { class: 'tz-btn ghost', onclick: function (e) { shareResult(m, correct, total, st, e.currentTarget); } }, '📤 اشتراکِ نتیجه'),
          h('button', { class: 'tz-btn', onclick: function () { runQuizIntro(m, stage); } }, 'آزمونِ تازه 🔁'))));
      if (pct >= 40) { tzConfetti(stage); tzSound('finish'); }
    }
    function reviewWrong() {
      clear(stage);
      var wrap = h('div', { class: 'tz-review' });
      wrap.appendChild(h('h3', { class: 'tz-lt' }, '🔍 مرورِ اشتباه‌ها — با هم درستشان کنیم'));
      review.forEach(function (rv, k) {
        var q = rv.q, card = h('div', { class: 'tz-rvcard' });
        card.appendChild(h('div', { class: 'tz-rvhead' }, 'اشتباهِ ' + toFa(k + 1) + ' — سرنخ: ' + (q.tag || '')));
        card.appendChild(h('p', { class: 'tz-qprompt' }, q.prompt));
        if (q.refs) card.appendChild(refsPanel(q.refs));
        if (q.grid) card.appendChild(gridPanel(q.grid));
        if (q.matrix) card.appendChild(matrixPanel(q.matrix));
        if (q.series) card.appendChild(seriesPanel(q.series));
        var opts = h('div', { class: 'tz-opts' + (q.wide ? ' wide' : '') });
        q.options.forEach(function (o, i) {
          var cls = 'tz-opt' + (i === q.answer ? ' ok' : (i === rv.chosen ? ' bad' : ''));
          var b = h('div', { class: cls }, q.render(o), h('span', { class: 'tz-opt-n' }, toFa(i + 1)));
          if (i === q.answer) b.appendChild(h('span', { class: 'tz-rvtag ok' }, 'پاسخِ درست'));
          else if (i === rv.chosen) b.appendChild(h('span', { class: 'tz-rvtag bad' }, 'انتخابِ تو'));
          opts.appendChild(b);
        });
        card.appendChild(opts);
        card.appendChild(h('div', { class: 'tz-fb ok' }, '💡 ' + q.why));
        wrap.appendChild(card);
      });
      wrap.appendChild(h('div', { class: 'tz-lnav' },
        h('button', { class: 'tz-btn ghost', onclick: function () { runPractice(m, stage); } }, 'تمرینِ بیشتر'),
        h('button', { class: 'tz-btn', onclick: function () { runQuizIntro(m, stage); } }, 'آزمونِ تازه 🔁')));
      clear(stage); stage.appendChild(wrap);
    }
    draw();
  }

